import re
import os
from pathlib import Path

def test_no_hardcoded_secrets_in_codebase():
    """Scan codebase for hardcoded secrets"""
    secret_patterns = [
        r'api[_-]?key\s*=\s*["\'][a-zA-Z0-9_-]{20,}["\']',
        r'sk_test_[a-zA-Z0-9]{24,}',
        r'password\s*=\s*["\'][^"\'{]{8,}["\']',
        r'secret\s*=\s*["\'][^"\'{]{16,}["\']'
    ]

    violations = []
    for root, dirs, files in os.walk('.'):
        # Skip test and venv directories
        dirs[:] = [d for d in dirs if d not in ['.git', 'venv', 'node_modules', '__pycache__']]

        for file in files:
            if file.endswith(('.py', '.js', '.ts', '.yml', '.yaml')):
                file_path = Path(root) / file
                try:
                    content = file_path.read_text()
                    for pattern in secret_patterns:
                        if re.search(pattern, content, re.IGNORECASE):
                            violations.append(f'{file_path}: Potential secret detected')
                except:
                    pass

    assert len(violations) == 0, f'Hardcoded secrets found: {violations}'
